B.a_t=new A.b0("If they insist, finish or cancel the job in the app and report it with 'Report a concern'.")
B.abD=s([B.a_s,B.a_t],t.f)
B.XR=new A.bd("m-incase-cash","The customer asks to pay cash or outside the app","Decline. Keep it on YCYC.",B.abD)
